"""Finalize B1-prime only after every required artifact and rerun is complete."""
from pathlib import Path
import collections,json,subprocess
from qualification.font04.metrics import sha
from qualification.font04.b1_audit import runtime
BASE=Path('qualification/font04');ROOT=BASE/'local'


def main():
    for name in ['prime-causal','prime-causal-extension']:
        for split in ['train','validation','test']+(['financial'] if name=='prime-causal' else []):
            root=ROOT/name/split;source=sha(root/'source.json');decisions=json.loads((root/'decisions.json').read_text());evaluation=json.loads((root/'evaluated.json').read_text());floor=json.loads((root/'floor-control-evaluated.json').read_text())
            assert decisions['source_sha256']==source,(name,split,'stale decisions')
            assert evaluation['decisions_sha256']==sha(root/'decisions.json'),(name,split,'stale evaluation')
            assert floor['source_sha256']==source,(name,split,'stale floor control')
            assert sum(r['renderer']=='analytic' for r in evaluation['records'])==sum(r['renderer']=='pdfium' for r in evaluation['records']),(name,split,'missing analytic primary')
            assert sum(r['renderer']=='analytic' for r in floor['records'])==sum(r['renderer']=='pdfium' for r in floor['records']),(name,split,'missing analytic floor arm')
    a=json.loads((BASE/'checkpoint-A.json').read_text());assert a['schema']=='font04-checkpoint-a-prime-v1'
    verification=json.loads((BASE/'prime-verification.json').read_text());metrics={arm:json.loads((BASE/(stem+'-scorecard.json')).read_text()) for arm,stem in [('B1','financial-experimental-v2'),('P0','financial-B1prime-P0'),('P','financial-B1prime-P'),('PV','financial-B1prime-PV')]}
    assert sha(ROOT/'financial-B1prime-default.pdf')==sha(ROOT/'financial-main.pdf')==sha(ROOT/'financial-default.pdf')
    assert sha(ROOT/'financial-B1prime-PV-repeat.pdf')==sha(ROOT/'financial-B1prime-PV.pdf')
    review=json.loads((BASE/'financial-B1prime-PV-review-manifest.json').read_text());directory=Path(review['review_pdf']).parent;selection=json.loads((directory/'selection.json').read_text());judgments=json.loads((directory/'judgments-template.json').read_text())
    assert 277 in selection['random_rejected'];assert review['random_rejected_members']>=50
    assert not (directory/'revealed-judgments.json').exists();assert all(j['U'] is None and j['V'] is None for j in judgments['judgments'])
    chosen=metrics['PV']['metrics']['analytic']['all'];assert chosen['n']==291
    assert abs(a['populations']['financial']['headline']['analytic']['mean_error']['A0']-chosen['default_mean'])<1e-6, 'Phase A/B1 default reference mismatch'
    pv=verification['arms']['financial-B1prime-PV'];conditions=dict(a=chosen['mean']<=chosen['default_mean'] and chosen['p95']<=chosen['default_p95'],b=pv['net_retired']>0,c=Path(review['review_pdf']).exists() and (directory/'sealed-key.json').exists())
    assert all(conditions.values())
    plan=json.loads((ROOT/'financial-B1prime-P.pdf.font04/plan.json').read_text());support=collections.Counter(x['status'] for x in plan['noise_support'])
    assert sha(BASE/'p2-preregistration.json')=='a4f9ccd3a7e51d719946be80f7cc9a297de7ca22285e8755e5e26e415e7db466'
    raster=json.loads((BASE/'prime-raster-identity.json').read_text());assert all(raster.values())
    ledgers={}
    witness_counts={r['member']:r['witnesses'] for r in plan['noise_support']}
    ownership=json.loads((BASE/'owned-component-ledger.json').read_text())
    for arm,stem in [('B1','financial-experimental-v2'),('P0','financial-B1prime-P0'),('P','financial-B1prime-P'),('PV','financial-B1prime-PV')]:
        pp=json.loads((ROOT/(stem+'.pdf.font04')/'plan.json').read_text());rr=pp['rejection_ledger']
        for row in rr:
            row['checks']=dict(row.get('checks',{}))
            if 'insufficient_noise_witnesses' in row['reasons']:row['checks']['noise_witnesses']=dict(value=witness_counts[row['member']],limit=2)
            if 'unexplained_owned_ink' in row['reasons']:row['checks']['unexplained_owned_ink']=dict(value=[c for c in ownership['components'] if c['member']==row['member'] and c['fires']],limit=ownership['policy'])
        ledgers[arm]=rr
    (BASE/'prime-rejection-ledgers.json').write_text(json.dumps(ledgers,separators=(',',':'))+'\n')
    result=dict(schema='font04-checkpoint-b1-prime-v1',chosen_arm='PV',population='All 291 visible e; 13-page P3 financial document',B2_conditions=conditions,B2_decision='AUTHORIZED: proceed with same star grouping, operating point 1.0, original hard vetoes plus ownership-aware veto; stop at Checkpoint B2.',reviewer_state='PENDING: corrected accepted/rejected sheets issued sealed; no visual defect or false-rejection rate is imputed.',review=review,metrics=metrics,verification=verification,default_regenerated_sha256=sha(ROOT/'financial-B1prime-default.pdf'),deterministic_PV_repeat_sha256=sha(ROOT/'financial-B1prime-PV-repeat.pdf'),coordinate_test=dict(path=str(BASE/'coordinate-roundtrip.json'),sha256=sha(BASE/'coordinate-roundtrip.json')),noise_support=dict(support,insufficient_support_rejections=88,fewer_than_k=88,calibration_failures=0,k=2),frontier=dict(path=str(BASE/'prime-frontier.json'),sha256=sha(BASE/'prime-frontier.json'),scope='P controls; PV selected complete output independently scored; operating point remains fixed at 1.0.'),phase_A=dict(path=str(BASE/'checkpoint-A.json'),sha256=sha(BASE/'checkpoint-A.json')),runtime={name:runtime(ROOT/(name+'.time')) for name in ['B1prime-default','B1prime-P0','B1prime-P','B1prime-PV','B1prime-PV-repeat']},failure_classifications=[dict(classification='measurement',finding='Half-canvas-pixel inverse corrected; B1 original reviewer numbers reproduced before edits; pre-fix line-frame conclusions superseded.'),dict(classification='algorithm',finding='Missing owned-ink veto corrected; glyph-277 exact default program and placement survive.'),dict(classification='data',finding='Corrected sealed review remains unresolved until independent judgments.'),dict(classification='algorithm',finding='Net six programs retired but complete PV PDF grows 89 bytes; serialization overhead is reported, not used to falsify reuse.')],raster_identity=raster,calibration=dict(primary=str(BASE/'prime-calibration.json'),extension=str(BASE/'prime-calibration-extension.json'),known_material_harm_catch=json.loads((BASE/'prime-calibration.json').read_text())['known_material_harm_catch']),rejection_ledgers=dict(path=str(BASE/'prime-rejection-ledgers.json'),sha256=sha(BASE/'prime-rejection-ledgers.json')),P2='not generated, rendered, inspected as a population, or modified; preregistration hash unchanged')
    (BASE/'checkpoint-B1prime.json').write_text(json.dumps(result,indent=2)+'\n')
    paths=[ROOT/'prime-phase-a-renderer-floors.json',ROOT/'financial-main.pdf',ROOT/'financial-default.pdf',ROOT/'financial-B1prime-default.pdf',ROOT/'financial-experimental-v2.pdf',ROOT/'financial-B1prime-P0.pdf',ROOT/'financial-B1prime-P.pdf',ROOT/'financial-B1prime-PV.pdf',ROOT/'financial-B1prime-PV-repeat.pdf']
    for p in [ROOT/'financial-B1prime-P0.pdf.font04',ROOT/'financial-B1prime-P.pdf.font04',ROOT/'financial-B1prime-PV.pdf.font04',ROOT/'financial-B1prime-P0-review',ROOT/'financial-B1prime-PV-review',ROOT/'prime-causal',ROOT/'prime-causal-extension',ROOT/'prime-frontier',ROOT/'review-reproduction']:
        paths.extend(x for x in p.rglob('*') if x.is_file())
    manifest=dict(schema='font04-b1-prime-artifacts-v1',artifacts=[dict(path=str(p),bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(set(paths))],key_policy='Key files are separate, local, mode 0600, never opened by the authoring/scoring process; no reveal was performed.')
    (BASE/'prime-artifact-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    lines=['\n## Checkpoint B1′ — corrected placement and owned-ink veto','', 'This checkpoint supersedes the pre-fix line-frame conclusions above. The independent B1 native/analytic and centroid/best-translation numbers were reproduced before edits. The physical inverse test passes 192 cells per arm (200/300/600 DPI × four x-heights × 16 phases), maximum fixed offset 0.015625 px; the old inverse fails every cell by the predicted 0.5/scale.','', '| Complete arm | Substituted e | Analytic mean | Analytic p95 | Net programs retired | PDF bytes |','|---|---:|---:|---:|---:|---:|']
    base=verification['default'];d=metrics['PV']['metrics']['analytic']['all'];lines.append(f"| default | 0 | {d['default_mean']:.6f} | {d['default_p95']:.6f} | 0 | {base['bytes']} |")
    for arm,stem in [('B1','financial-experimental-v2'),('P0','financial-B1prime-P0'),('P','financial-B1prime-P'),('PV','financial-B1prime-PV')]:
        m=metrics[arm];err=m['metrics']['analytic']['all'];v=verification['arms'][stem];lines.append(f"| {arm} | {m['substituted']} | {err['mean']:.6f} | {err['p95']:.6f} | {v['net_retired']} | {m['bytes']} |")
    lines+=['','P0 freezes all B1 membership and canonical assignments. Independently recomputed P has exactly the same assignments and byte-identical complete output. PV vetoes only glyph-277; the original default program and physical matrix are retained. Every connected source component is logged with area, contrast, distance and decision. Dirt not reproduced by default cannot trigger retention.','', 'The scorecards report both all 291 members and the actually substituted subset under PDFium, Poppler, 4× supersampled analytic and direct 16× winding coverage, including mean, p95 and worst-ten regression IDs. Native screens are accompanied by measured identical-outline floors; differences below those floors do not rank arms. The primary analytic and independent direct-outline metrics improve.','', 'All 88 insufficient-noise-support cases have fewer than k=2 witnesses; none failed calibration. The fixed frontier is remeasured at all 21 pre-existing grouping/threshold points. Star/1.0 remains fixed; the larger retirement at higher thresholds is a reviewer question, not an operating-point change.','', 'Corrected Phase A line-frame arms and floor controls were rerun on frozen cohorts/traces; [Checkpoint A](qualification/font04/checkpoint-A.md) supersedes the pre-fix shares and F-self/F-medoid conclusions. No product promotion follows without independent review.','', 'PV sealed sheets contain 96 accepted and 51 rejected members (including every veto firing), repeated words containing e, both renderers, reading size and 400%. Rejected candidates replace their current glyph in full page context. The key remains separate and unopened. **Reviewer pending:** material defects and over-rejection remain unresolved.','', 'Default is byte-identical to main; PV repeats deterministically. qpdf, OTS, extraction and native search checks pass for all arms. PV retires six net programs but grows the complete PDF by 89 bytes; P/P0 save 217 bytes. This byte tradeoff is retained for B2 diagnosis.','', '**B2 conditions: (a) PASS, (b) PASS, (c) PASS.** Proceed to all 55 frequent classes with the same method and stop at Checkpoint B2. P2 remains sealed; no default promotion or merge is authorized.','', 'Complete PDFs: `qualification/font04/local/financial-experimental-v2.pdf`, `financial-B1prime-P0.pdf`, `financial-B1prime-P.pdf`, `financial-B1prime-PV.pdf`, and `financial-B1prime-default.pdf` in the same directory. Corrected chosen review: `qualification/font04/local/financial-B1prime-PV-review/blinded-review.pdf`. See [checkpoint-B1prime.json](qualification/font04/checkpoint-B1prime.json), [prime-artifact-manifest.json](qualification/font04/prime-artifact-manifest.json) and per-arm scorecards for hashes, tails, floors and runtime.']
    report=Path('FONT_04_RESULTS.md');text=report.read_text();marker='\n## Checkpoint B1′ — corrected placement and owned-ink veto'
    if marker in text:text=text[:text.index(marker)]
    report.write_text(text+'\n'.join(lines)+'\n')
    print('B1-prime complete; B2 conditions',conditions)

if __name__=='__main__':main()
